omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.beginning_of_future_options_summary_message = ProtoField.new("Beginning Of Future Options Summary Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.beginningoffutureoptionssummarymessage", ftypes.STRING, nil, nil, nil, "This message indicates that the beginning and the end of day NB: Future Options Summary messages are to follow. Other messages (such as bulletins) can be interspersed with the summaries.")
