omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.beginning_of_options_summary_message = ProtoField.new("Beginning Of Options Summary Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.beginningofoptionssummarymessage", ftypes.STRING, nil, nil, nil, "This message indicates that the beginning and the end of day N: Option Summary messages are to follow. Other messages (such as bulletins) can be interspersed with the summaries.")
omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.beginning_of_strategy_summary_message = ProtoField.new("Beginning Of Strategy Summary Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.beginningofstrategysummarymessage", ftypes.STRING, nil, nil, nil, "This message indicates that the beginning or the end of day NS: Strategy Summary messages are to follow. Other messages can be interspersed with the summaries.")
omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.bulletins_message = ProtoField.new("Bulletins Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.bulletinsmessage", ftypes.STRING, nil, nil, nil, "Bulletins will be sent throughout the trading day. More than one message will be used if the bulletin is longer than 79 characters. The continuation character ‘0’ indicates that the bulletin continues to the next record. When a Trading instrument has been halted by the Bourse de Montréal Inc., a Bulletin Message explaining the reason for the halt will be transmitted. When the trading instrument is reinstated, another bulletin message explaining the news that accompanied the reinstatement will be transmitted. All records that make up a particular bulletin will be sent out together. No other message will be interspersed among the records that make up a complete bulletin.")
omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.circuit_assurance_message = ProtoField.new("Circuit Assurance Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.circuitassurancemessage", ftypes.STRING, nil, nil, nil, "This message is sent out if no messages are sent by SAM for more than one minute after the broadcast has started (i.e., at the termination of the Test Loop message). This will be an assurance that the line is up. This message will continue to be sent until the U: End of Transmission message is sent. The Circuit Assurance message will repeat the sequence number of the previous record transmitted (except if it is a re-transmit message), i.e. it will not increase the sequence number")
omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.end_of_sales_message = ProtoField.new("End Of Sales Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.endofsalesmessage", ftypes.STRING, nil, nil, nil, "The S: End of Sales message is sent when there is no more trading activity to be transmitted. This occurs after the closing of the market.")
omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.end_of_transmission_message = ProtoField.new("End Of Transmission Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.endoftransmissionmessage", ftypes.STRING, nil, nil, nil, "This message will be sent daily to indicate that the day’s transmission is complete. No HSVF messages will be transmitted afterwards. Transmission will resume the following day.")
omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.error_message = ProtoField.new("Error Message", "tmx.mx.solatcpretransmission.hsvf.v1.14.1.errormessage", ftypes.STRING)
