-- Handle changed preferences
function omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs_changed()

  -- Check if preferences have changed
  if show.application_messages ~= omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_application_messages then
    show.application_messages = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_application_messages
  end
  if show.headers ~= omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_headers then
    show.headers = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_headers
  end
  if show.repeating_groups ~= omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_repeating_groups then
    show.repeating_groups = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_repeating_groups
  end
  if show.structs ~= omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_structs then
    show.structs = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_structs
  end
  if show.indexes ~= omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_indexes then
    show.indexes = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.show_indexes
  end
