-- Bid Size
tmx_mx_solatcpretransmission_hsvf_v1_14_1.bid_size = {}

-- Size: Bid Size
tmx_mx_solatcpretransmission_hsvf_v1_14_1.bid_size.size = 5

-- Display: Bid Size
tmx_mx_solatcpretransmission_hsvf_v1_14_1.bid_size.display = function(value, buffer, offset, packet, parent)
  return "Bid Size: "..string.format("%.0f", value)
end

-- Dissect: Bid Size
tmx_mx_solatcpretransmission_hsvf_v1_14_1.bid_size.dissect = function(buffer, offset, packet, parent)
  local length = tmx_mx_solatcpretransmission_hsvf_v1_14_1.bid_size.size
  local range = buffer(offset, length)
  local text = range:string()
  local powers = { ["C"] = 2, ["D"] = 3, ["E"] = 4, ["F"] = 5, ["G"] = 6, ["H"] = 7, ["I"] = 8, ["J"] = 9 }
  local value = 0
  local power = 0

  for index = 1, #text do
    local character = text:sub(index, index)
    if powers[character] then
      power = powers[character]
    else
      value = value * 10 + (tonumber(character) or 0)
    end
  end

  value = value * (10 ^ power)

  local display = tmx_mx_solatcpretransmission_hsvf_v1_14_1.bid_size.display(value, buffer, offset, packet, parent)

  parent:add(omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.bid_size, range, value, display)

  return offset + length, value
end

