-- Dissect: Number Of Ask Orders
tmx_mx_solatcpretransmission_hsvf_v1_14_1.number_of_ask_orders.dissect = function(buffer, offset, packet, parent)
  local length = tmx_mx_solatcpretransmission_hsvf_v1_14_1.number_of_ask_orders.size
  local range = buffer(offset, length)
  local text = range:string()
  local powers = { ["C"] = 2, ["D"] = 3, ["E"] = 4, ["F"] = 5, ["G"] = 6, ["H"] = 7, ["I"] = 8, ["J"] = 9 }
  local value = 0
  local power = 0

  for index = 1, #text do
    local character = text:sub(index, index)
