-- Start Of Day Message
tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message = {}

-- Size: Start Of Day Message
tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message.size =
  tmx_mx_solatcpretransmission_hsvf_v1_14_1.exchange_id.size + 
  tmx_mx_solatcpretransmission_hsvf_v1_14_1.business_date.size

-- Display: Start Of Day Message
tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: Start Of Day Message
tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message.fields = function(buffer, offset, packet, parent)
  local index = offset

  -- Exchange Id: A
  index, exchange_id = tmx_mx_solatcpretransmission_hsvf_v1_14_1.exchange_id.dissect(buffer, index, packet, parent)

  -- Business Date: N
  index, business_date = tmx_mx_solatcpretransmission_hsvf_v1_14_1.business_date.dissect(buffer, index, packet, parent)

  return index
end

-- Dissect: Start Of Day Message
tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message.dissect = function(buffer, offset, packet, parent)
  if show.application_messages then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.start_of_day_message, buffer(offset, 0))
    local index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message.fields(buffer, offset, packet, parent)
    local length = index - offset
    parent:set_len(length)
    local display = tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return tmx_mx_solatcpretransmission_hsvf_v1_14_1.start_of_day_message.fields(buffer, offset, packet, parent)
  end
end

