  -- Number Of Entries: N
  index, number_of_entries = tmx_mx_solatcpretransmission_hsvf_v1_14_1.number_of_entries.dissect(buffer, index, packet, parent)

  -- Repeating: Tick Entry
  for tick_entry_index = 1, number_of_entries do
