  index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.trade_price_fraction_pair.dissect(buffer, index, packet, parent, trade_price_fraction_indicator)

  -- Net Change Sign: X
  index, net_change_sign = tmx_mx_solatcpretransmission_hsvf_v1_14_1.net_change_sign.dissect(buffer, index, packet, parent)

  -- Dependency element: Net Change Fraction Indicator
  local net_change_fraction_indicator = buffer(index + 7, 1):string()

