  index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.net_change_futures_trade_correction_message_fraction_pair.dissect(buffer, index, packet, parent, net_change_fraction_indicator)

  -- Price Indicator Marker: X
  index, price_indicator_marker = tmx_mx_solatcpretransmission_hsvf_v1_14_1.price_indicator_marker.dissect(buffer, index, packet, parent)

  -- Trade Number: X
  index, trade_number = tmx_mx_solatcpretransmission_hsvf_v1_14_1.trade_number.dissect(buffer, index, packet, parent)

  return index
