-- Ask Price Futures Depth Market Depth Level HF
tmx_mx_solatcpretransmission_hsvf_v1_14_1.ask_price_futures_depth_market_depth_level_hf = {}

-- Dissect: Ask Price Futures Depth Market Depth Level HF
tmx_mx_solatcpretransmission_hsvf_v1_14_1.ask_price_futures_depth_market_depth_level_hf.dissect = function(buffer, offset, packet, parent, ask_price_futures_depth_opening, ask_price_fraction_indicator, ask_price_fraction_indicator)
  -- Dissect Ask Price Futures Depth Market Depth Level HF Opening Pair
  if ask_price_futures_depth_opening == "OUV" and ask_price_fraction_indicator == "0" then
    return tmx_mx_solatcpretransmission_hsvf_v1_14_1.ask_price_futures_depth_market_depth_level_hf_opening_pair.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Ask Price Futures Depth Numeric Negative Whole Pair
  if ask_price_fraction_indicator == "A" then
    return tmx_mx_solatcpretransmission_hsvf_v1_14_1.ask_price_futures_depth_numeric_negative_whole_pair.dissect(buffer, offset, packet, parent)
