end

-- Dissect Fields: Futures Trade Message
tmx_mx_solatcpretransmission_hsvf_v1_14_1.futures_trade_message.fields = function(buffer, offset, packet, parent)
  local index = offset

  -- Exchange Id: A
  index, exchange_id = tmx_mx_solatcpretransmission_hsvf_v1_14_1.exchange_id.dissect(buffer, index, packet, parent)

  -- Future Product: Struct of 4 fields
  index, future_product = tmx_mx_solatcpretransmission_hsvf_v1_14_1.future_product.dissect(buffer, index, packet, parent)

  -- Volume: N
  index, volume = tmx_mx_solatcpretransmission_hsvf_v1_14_1.volume.dissect(buffer, index, packet, parent)

  -- Dependency element: Trade Price Fraction Indicator
  local trade_price_fraction_indicator = buffer(index + 7, 1):string()

  -- Trade Price Fraction Pair: Runtime Type with 8 branches
  index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.trade_price_fraction_pair.dissect(buffer, index, packet, parent, trade_price_fraction_indicator)

  -- Net Change Sign: X
  index, net_change_sign = tmx_mx_solatcpretransmission_hsvf_v1_14_1.net_change_sign.dissect(buffer, index, packet, parent)

  -- Dependency element: Net Change Fraction Indicator
  local net_change_fraction_indicator = buffer(index + 7, 1):string()

  -- Net Change Futures Trade Message Fraction Pair: Runtime Type with 8 branches
  index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.net_change_futures_trade_message_fraction_pair.dissect(buffer, index, packet, parent, net_change_fraction_indicator)

  -- Price Indicator Marker: X
  index, price_indicator_marker = tmx_mx_solatcpretransmission_hsvf_v1_14_1.price_indicator_marker.dissect(buffer, index, packet, parent)

  -- Trade Number: X
  index, trade_number = tmx_mx_solatcpretransmission_hsvf_v1_14_1.trade_number.dissect(buffer, index, packet, parent)

  -- Auction Id: X
  index, auction_id = tmx_mx_solatcpretransmission_hsvf_v1_14_1.auction_id.dissect(buffer, index, packet, parent)

  return index
end

