-- Remaining Bytes For: Server Frame
local server_frame_bytes_remaining = function(buffer, index, available)
  -- Calculate the number of bytes remaining
  local remaining = available - index

  -- A message runs to the first terminator byte: scan for it
  local terminator = 3
  local current = 0
  while current < remaining and buffer(index + current, 1):uint() ~= terminator do
    current = current + 1
  end

  -- The terminator is not in the bytes available yet: ask for one more segment
  if current >= remaining then
    return -DESEGMENT_ONE_MORE_SEGMENT
  end

  -- The message includes the terminator byte it ends on
  current = current + 1

  return remaining, current
end

-- Server Packet
tmx_mx_solatcpretransmission_hsvf_v1_14_1.server_packet = {}

-- Verify required size of Tcp packet
tmx_mx_solatcpretransmission_hsvf_v1_14_1.server_packet.requiredsize = function(buffer)
  return buffer:len() >= tmx_mx_solatcpretransmission_hsvf_v1_14_1.hsvf_stx.size + tmx_mx_solatcpretransmission_hsvf_v1_14_1.message_header.size
end

-- Dissect Server Packet
tmx_mx_solatcpretransmission_hsvf_v1_14_1.server_packet.dissect = function(buffer, packet, parent)
  local index = 0

  -- Dependency for Server Frame
  local end_of_payload = buffer:len()

  -- Server Frame: Struct of 4 fields
  while index < end_of_payload do

    -- Are minimum number of bytes are available?
    local available, size_of_server_frame = server_frame_bytes_remaining(buffer, index, end_of_payload)

    if available > 0 then
      -- Dissect this message within a buffer bounded to its own frame
      local frame = buffer(0, index + size_of_server_frame):tvb()
      index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.server_frame.dissect(frame, index, packet, parent, size_of_server_frame)
    else
      -- More bytes needed, so set packet information
      packet.desegment_offset = index
      packet.desegment_len = -(available)

      -- Claim the whole buffer: tcp keeps the bytes from desegment_offset for reassembly
      return end_of_payload
    end
  end

  return index
end

