tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_body.dissect = function(buffer, offset, packet, parent, client_message_type)
  local dissect = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_body.dispatch[client_message_type]
  if dissect then
    return dissect(buffer, offset, packet, parent)
  end

  return offset
end

-- Client Message Header
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header = {}

-- Size: Client Message Header
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.size =
  tmx_mx_solatcpretransmission_hsvf_v1_14_1.sequence_number.size + 
