-- Dissect Fields: Client Message Header
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.fields = function(buffer, offset, packet, parent)
  local index = offset

  -- Sequence Number: N
  index, sequence_number = tmx_mx_solatcpretransmission_hsvf_v1_14_1.sequence_number.dissect(buffer, index, packet, parent)

  -- Client Message Type: X
  index, client_message_type = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_type.dissect(buffer, index, packet, parent)

  return index
end

-- Dissect: Client Message Header
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.dissect = function(buffer, offset, packet, parent)
  if show.headers then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.client_message_header, buffer(offset, 0))
    local index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.fields(buffer, offset, packet, parent)
    local length = index - offset
    parent:set_len(length)
    local display = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.fields(buffer, offset, packet, parent)
