-- Client Frame
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame = {}

-- Display: Client Frame
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: Client Frame
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame.fields = function(buffer, offset, packet, parent, size_of_client_frame)
  local index = offset

  -- Hsvf Stx: character
  index, hsvf_stx = tmx_mx_solatcpretransmission_hsvf_v1_14_1.hsvf_stx.dissect(buffer, index, packet, parent)

  -- Client Message Header: Struct of 2 fields
  index, client_message_header = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.dissect(buffer, index, packet, parent)

  -- Dependency element: Client Message Type
  local client_message_type = trim_right_spaces(buffer(index - 2, 2):string())

  -- Client Message Body: Runtime Type with 3 branches
  index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_body.dissect(buffer, index, packet, parent, client_message_type)

  -- Hsvf Etx: character
  index, hsvf_etx = tmx_mx_solatcpretransmission_hsvf_v1_14_1.hsvf_etx.dissect(buffer, index, packet, parent)

  return index
end

-- Dissect: Client Frame
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame.dissect = function(buffer, offset, packet, parent, size_of_client_frame)
  local index = offset + size_of_client_frame

  -- Optionally add group/struct element to protocol tree
  if show.structs then
    parent = parent:add(omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.fields.client_frame, buffer(offset, 0))
    local current = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame.fields(buffer, offset, packet, parent, size_of_client_frame)
    parent:set_len(size_of_client_frame)
    local display = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame.display(buffer, packet, parent)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame.fields(buffer, offset, packet, parent, size_of_client_frame)

    return index
  end
end

-- Remaining Bytes For: Client Frame
local client_frame_bytes_remaining = function(buffer, index, available)
  -- Calculate the number of bytes remaining
  local remaining = available - index

  -- A message runs to the first terminator byte: scan for it
  local terminator = 3
  local current = 0
  while current < remaining and buffer(index + current, 1):uint() ~= terminator do
    current = current + 1
  end

  -- The terminator is not in the bytes available yet: ask for one more segment
  if current >= remaining then
    return -DESEGMENT_ONE_MORE_SEGMENT
  end

  -- The message includes the terminator byte it ends on
  current = current + 1

  return remaining, current
end

-- Client Packet
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_packet = {}

-- Verify required size of Tcp packet
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_packet.requiredsize = function(buffer)
  return buffer:len() >= tmx_mx_solatcpretransmission_hsvf_v1_14_1.hsvf_stx.size + tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_message_header.size
end

-- Dissect Client Packet
tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_packet.dissect = function(buffer, packet, parent)
  local index = 0

  -- Dependency for Client Frame
  local end_of_payload = buffer:len()

  -- Client Frame: Struct of 4 fields
  while index < end_of_payload do

    -- Are minimum number of bytes are available?
    local available, size_of_client_frame = client_frame_bytes_remaining(buffer, index, end_of_payload)

    if available > 0 then
      -- Dissect this message within a buffer bounded to its own frame
      local frame = buffer(0, index + size_of_client_frame):tvb()
      index = tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_frame.dissect(frame, index, packet, parent, size_of_client_frame)
    else
      -- More bytes needed, so set packet information
      packet.desegment_offset = index
      packet.desegment_len = -(available)

      -- Claim the whole buffer: tcp keeps the bytes from desegment_offset for reassembly
      return end_of_payload
    end
  end

  return index
end


