-- Initialize Dissector
function omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.init()
end

-- Connection roles for Tmx Mx SolaTcpRetransmission Hsvf 1.14.1: Client is the initiator, Server is the acceptor
-- Initiator endpoint of each conversation, recorded from its first frame
local initiators = {}

-- Conversations whose first frame proved to be the acceptor's: the heuristic swaps the sides
local swapped = {}

-- Endpoint key of an address and port
local function endpoint(address, port)
  return tostring(address)..":"..tostring(port)
end


-- Conversation key, the same in both directions
local function conversation(packet)
  local source = endpoint(packet.src, packet.src_port)
  local destination = endpoint(packet.dst, packet.dst_port)

  if source < destination then
    return source.." "..destination
  end

  return destination.." "..source
end


-- Connection role of the frame's sender
tmx_mx_solatcpretransmission_hsvf_v1_14_1.role = function(packet)
  if omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.assume_role == 1 then
    return "initiator"
  end

  if omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.assume_role == 2 then
    return "acceptor"
  end

  local acceptor_port = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.acceptor_port

  if acceptor_port ~= 0 and packet.dst_port == acceptor_port then
    return "initiator"
  end

  if acceptor_port ~= 0 and packet.src_port == acceptor_port then
    return "acceptor"
  end

  local key = conversation(packet)
  local sender = endpoint(packet.src, packet.src_port)

  if initiators[key] == nil then
    initiators[key] = sender
  end

  local sender_initiated = initiators[key] == sender

  if omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.prefs.swap_sides then
    sender_initiated = not sender_initiated
  end

  if swapped[key] then
    sender_initiated = not sender_initiated
  end

  if sender_initiated then
    return "initiator"
  end

  return "acceptor"
end


-- Swap the resolved sides of the frame's conversation
tmx_mx_solatcpretransmission_hsvf_v1_14_1.swap = function(packet)
  local key = conversation(packet)
  swapped[key] = not swapped[key]
end


-- Dissector for Tmx Mx SolaTcpRetransmission Hsvf 1.14.1
function omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.dissector(buffer, packet, parent)
  -- Set protocol name
  packet.cols.protocol = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.name

  -- Dissect protocol
  local protocol = parent:add(omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1, buffer(), omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.description, "("..buffer:len().." Bytes)")
  local role = tmx_mx_solatcpretransmission_hsvf_v1_14_1.role(packet)

  if role == "initiator" then
    return tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_packet.dissect(buffer, packet, protocol)
  end

  return tmx_mx_solatcpretransmission_hsvf_v1_14_1.server_packet.dissect(buffer, packet, protocol)
end


