-- Dissector Heuristic for Tmx Mx SolaTcpRetransmission Hsvf 1.14.1 (Tcp)
local function omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1_tcp_initiator_heuristic(buffer, packet, parent)
  -- Verify packet length
  if not tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_packet.requiredsize(buffer) then return false end

  -- Verify Hsvf Stx
  if not tmx_mx_solatcpretransmission_hsvf_v1_14_1.hsvf_stx.client_packet_verify(buffer) then return false end

  -- Verify the frame matches this tcp client packet message dispatch
  if not tmx_mx_solatcpretransmission_hsvf_v1_14_1.client_packet.fingerprint(buffer) then return false end

  -- Protocol is valid, set conversation and dissect this packet
  packet.conversation = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1
  omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.dissector(buffer, packet, parent)

  return true
end

-- Dissector Heuristic for Tmx Mx SolaTcpRetransmission Hsvf 1.14.1 (Tcp)
local function omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1_tcp_acceptor_heuristic(buffer, packet, parent)
  -- Verify packet length
  if not tmx_mx_solatcpretransmission_hsvf_v1_14_1.server_packet.requiredsize(buffer) then return false end

  -- Verify Hsvf Stx
  if not tmx_mx_solatcpretransmission_hsvf_v1_14_1.hsvf_stx.server_packet_verify(buffer) then return false end

  -- Verify the frame matches this tcp server packet message dispatch
  if not tmx_mx_solatcpretransmission_hsvf_v1_14_1.server_packet.fingerprint(buffer) then return false end

  -- Protocol is valid, set conversation and dissect this packet
  packet.conversation = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1
  omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1.dissector(buffer, packet, parent)

  return true
end

-- Dissector Heuristic for Tmx Mx SolaTcpRetransmission Hsvf 1.14.1 (Tcp): apply the heuristic of the sender's connection role
local function omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1_tcp_heuristic(buffer, packet, parent)
  local role = tmx_mx_solatcpretransmission_hsvf_v1_14_1.role(packet)
  local initiator = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1_tcp_initiator_heuristic
  local acceptor = omi_tmx_mx_solatcpretransmission_hsvf_v1_14_1_tcp_acceptor_heuristic

  local first, second = initiator, acceptor

  if role == "acceptor" then
    first, second = acceptor, initiator
  end

  if first(buffer, packet, parent) then
    return true
  end

  -- The other side may have sent this conversation's first frame: swap, and swap back if it cannot claim either
  tmx_mx_solatcpretransmission_hsvf_v1_14_1.swap(packet)

  if second(buffer, packet, parent) then
    return true
  end

  tmx_mx_solatcpretransmission_hsvf_v1_14_1.swap(packet)

  return false
end

